bool compareFiles(const std::string &p1, const std::string &p2) {
  std::ifstream f1(p1, std::ifstream::binary | std::ifstream::ate);
  std::ifstream f2(p2, std::ifstream::binary | std::ifstream::ate);

  if (f1.fail() || f2.fail()) {
    return false;
  }

  if (f1.tellg() != f2.tellg()) {
    return false;
  }

  f1.seekg(0, std::ifstream::beg);
  f2.seekg(0, std::ifstream::beg);
  return std::equal(std::istreambuf_iterator<char>(f1.rdbuf()),
                    std::istreambuf_iterator<char>(),
                    std::istreambuf_iterator<char>(f2.rdbuf()));
}

void removeUnusedFile(const std::string &srcPath, const std::string &desPath,
                      const std::string &srcFileExt,
                      const std::string &desFileExt) {
  string FilePath;
  if ((!bf::is_directory(srcPath)) || (!bf::is_directory(desPath))) {
    return;
  }
  for (const auto &file : bf::directory_iterator(desPath)) {
    if (srcFileExt.empty()) {
      FilePath = srcPath + file.path().filename().string();
    } else {
      FilePath = srcPath + file.path().stem().string() + srcFileExt;
    }
    if (bf::is_regular_file(file.status()) && !bf::exists(FilePath)) {
      if (desFileExt.empty()) {
        bf::remove(file.path().string());
      } else {
        bf::remove(desPath + file.path().stem().string() + desFileExt);
      }
    }
  }
  return;
}

